def _required_hailo_full_preupload_gate(
    profile_payload: Mapping[str, Any] | None,
    backend_artifact_decisions: Mapping[str, Any] | None,
) -> Dict[str, Any]:
    """Require every requested Full-only Canary HEF before remote dispatch.

    ``recorded_hailo_full_contracts`` is written only after the existing HEF
    receipt and artifact verification succeeds.  This gate deliberately uses
    that established authority instead of inventing another hash, cache, or
    receipt format.
    """

    profile = (
        dict(profile_payload or {})
        if isinstance(profile_payload, Mapping) else {}
    )
    canary = (
        dict(profile.get("quality_canary") or {})
        if isinstance(profile.get("quality_canary"), Mapping) else {}
    )
    enabled = bool(
        canary.get("enabled") is True
        and str(canary.get("execution_scope") or "").strip() == "full_only"
    )
    if not enabled:
        return {
            "enabled": False,
            "ok": True,
            "requested_backends": [],
            "ready_backends": [],
            "missing_backends": [],
            "ambiguous_backends": [],
            "observed_promotions": [],
            "hailo_axes": {},
        }

    requested_backends: List[str] = []
    for raw in canary.get("full_run_ids") or []:
        if not isinstance(raw, Mapping):
            continue
        backend = str(raw.get("backend") or "").strip().lower()
        if backend.startswith("hailo") and backend not in requested_backends:
            requested_backends.append(backend)

    # This is a Hailo artifact gate, not a generic Full-only Canary gate.
    # DeepX-only canaries have no HEF to attest and must be allowed to reach
    # their own artifact binding and remote executor.  Once any Hailo backend
    # is requested, the existing all-or-nothing receipt check below remains
    # fail-closed.
    if not requested_backends:
        return {
            "enabled": False,
            "ok": True,
            "requested_backends": [],
            "ready_backends": [],
            "missing_backends": [],
            "ambiguous_backends": [],
            "observed_promotions": [],
            "hailo_axes": {},
        }

    decisions = (
        dict(backend_artifact_decisions or {})
        if isinstance(backend_artifact_decisions, Mapping) else {}
    )
    promotions = [
        dict(raw) for raw in decisions.get("recorded_hailo_full_contracts") or []
        if isinstance(raw, Mapping)
    ]

    def _receipt_attested(raw: Mapping[str, Any]) -> bool:
        return all(
            str(raw.get(key) or "").strip()
            for key in (
                "artifact_path",
                "artifact_sha256",
                "hailo_build_receipt_file_sha256",
                "hailo_build_receipt_identity_sha256",
            )
        )

    ready_backends: List[str] = []
    missing_backends: List[str] = []
    ambiguous_backends: List[str] = []
    for backend in requested_backends:
        matches = [
            raw for raw in promotions
            if _artifact_hailo_hw_matches(backend, raw.get("backend"))
            and _receipt_attested(raw)
        ]
        if len(matches) == 1:
            ready_backends.append(backend)
        else:
            missing_backends.append(backend)
            if len(matches) > 1:
                ambiguous_backends.append(backend)

    hailo = (
        dict(profile.get("hailo_build") or {})
        if isinstance(profile.get("hailo_build"), Mapping) else {}
    )
    hailo_axes = {
        "mode": str(hailo.get("mode") or ""),
        "preset": str(hailo.get("preset") or ""),
        "optimization_level": hailo.get("optimization_level"),
        "calib_count": hailo.get("calib_count"),
        "calib_batch_size": hailo.get("calib_batch_size"),
        "calibration_storage": hailo.get("calibration_storage"),
        "cache_integrity": hailo.get("cache_integrity"),
    }
    observed_promotions = [
        {
            "backend": str(raw.get("backend") or ""),
            "artifact_path": str(raw.get("artifact_path") or ""),
            "receipt_attested": _receipt_attested(raw),
        }
        for raw in promotions
    ]
    return {
        "enabled": True,
        "ok": not missing_backends,
        "requested_backends": requested_backends,
        "ready_backends": ready_backends,
        "missing_backends": missing_backends,
        "ambiguous_backends": ambiguous_backends,
        "observed_promotions": observed_promotions,
        "hailo_axes": hailo_axes,
    }


def _terminal_remote_failure_from_execution_artifacts_v27516(
    artifacts: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Return the earliest structured rc=70 failure from remote dispatches."""

    candidates: list[dict[str, Any]] = []
    for name, raw_path in dict(artifacts or {}).items():
        key = str(name or "")
        if not (
            key.startswith("remote_benchmark_status")
            and key.endswith("_json")
        ):
            continue
        path = Path(str(raw_path or ""))
        if not path.is_file():
            continue
        status_payload = read_json(path, default={}) or {}
        if not isinstance(status_payload, Mapping):
            continue
        remote_output = status_payload.get("remote_output")
        if not isinstance(remote_output, Mapping):
            continue
        primary = remote_output.get("primary_failure")
        if not isinstance(primary, Mapping):
            continue
        if not bool(remote_output.get("terminal_remote_failure")):
            continue
        remote_rc = int(
            remote_output.get("remote_rc") or primary.get("remote_rc") or 0
        )
        failure_kind = str(primary.get("failure_kind") or "")
        if not (
            remote_rc == 70
            or failure_kind == "terminal_remote_storage_failure"
        ):
            continue
        row = dict(primary)
        row["remote_status_artifact"] = str(path)
        row["hardware_target_id"] = str(
            status_payload.get("hardware_target_id") or
            (status_payload.get("host") or {}).get("id")
            if isinstance(status_payload.get("host"), Mapping)
            else status_payload.get("hardware_target_id") or ""
        )
        row["local_run_dir"] = str(remote_output.get("local_run_dir") or "")
        candidates.append(row)
    if not candidates:
        return {}
    candidates.sort(
        key=lambda row: (
            str(row.get("primary_error_at") or "9999-12-31T23:59:59Z"),
            str(row.get("remote_status_artifact") or ""),
        )
    )
    return candidates[0]


def _native_energy_payload_v272(
    energy_state: Mapping[str, Any] | None,
    key: str,
    *,
    run_dir: str | Path | None = None,
) -> dict[str, Any]:
    """Load one archived Native Energy payload referenced by stage state."""
    if not isinstance(energy_state, Mapping):
        return {}
    raw_path = str(energy_state.get(key) or "").strip()
    if not raw_path:
        return {}
    path = Path(raw_path)
    candidates = [path]
    if not path.is_absolute() and run_dir:
        candidates.insert(0, Path(run_dir) / path)
    for candidate in candidates:
        if not candidate.is_file():
            continue
        payload = read_json(candidate, default={}) or {}
        if isinstance(payload, Mapping):
            return dict(payload)
    return {}


def _native_model_selection_decision(
    valid_models: Sequence[str],
    excluded_models: Mapping[str, Any],
) -> tuple[List[str], List[str]]:
    """Keep model preflight failures local while another model can run."""

    runnable = [str(model) for model in valid_models if str(model)]
    if runnable or not excluded_models:
        return runnable, []
    blocking: List[str] = []
    for raw_model, raw_report in sorted(excluded_models.items()):
        model = str(raw_model)
        report = raw_report if isinstance(raw_report, Mapping) else {}
        blocking.append(
            str(report.get("failure_reason") or f"benchmark_set_invalid:{model}")
        )
    return runnable, blocking


def _native_case_selection_decision(
    models: Sequence[str],
    *,
    case_policy: str,
    case_map: Mapping[str, Sequence[Any]],
    available_case_map: Mapping[str, Sequence[str]],
    ignored_models: Sequence[str] = (),
) -> tuple[List[str], Dict[str, List[str]], Dict[str, Dict[str, Any]], List[str]]:
    """Resolve Native cases without letting one model cancel its peers.

    Structural selection errors (malformed/empty global policy, unknown model
    keys) remain global.  Model-addressable errors are returned as model-local
    exclusions so independent models can still transfer, execute and measure
    energy.  A model with any invalid explicit case request is excluded as a
    whole rather than silently shrinking the user's requested cohort.
    """

    requested_models = [str(model) for model in models if str(model)]
    requested_set = set(requested_models)
    ignored_set = {str(model) for model in ignored_models if str(model)}
    global_errors: List[str] = []
    exclusions: Dict[str, Dict[str, Any]] = {}
    effective_map: Dict[str, List[str]] = {}

    def _exclude(
        model: str,
        reason: str,
        *,
        category: str,
        requested: Sequence[str],
        available: Sequence[str],
    ) -> None:
        exclusions[str(model)] = {
            "valid": False,
            "preflight_scope": "model",
            "category": category,
            "failure_reason": reason,
            "requested_cases": [str(value) for value in requested],
            "available_cases": [str(value) for value in available],
        }

    if case_policy == "case_map_only":
        if not case_map:
            global_errors.append("case_map_only_requires_non_empty_map")
        unknown_models = sorted(
            set(str(model) for model in case_map)
            .difference(requested_set)
            .difference(ignored_set)
        )
        if unknown_models:
            global_errors.append(
                "case_map_unknown_models:" + ",".join(unknown_models)
            )
        for model in requested_models:
            available = [
                str(value) for value in list(available_case_map.get(model) or [])
                if str(value)
            ]
            if model not in case_map:
                _exclude(
                    model,
                    f"case_map_missing_requested_models:{model}",
                    category="model_case_selection",
                    requested=[],
                    available=available,
                )
                continue
            selected = [
                str(value).strip()
                for value in list(case_map.get(model) or [])
                if str(value).strip()
            ]
            if not selected:
                _exclude(
                    model,
                    f"case_map_cases_empty:{model}",
                    category="model_case_selection",
                    requested=selected,
                    available=available,
                )
                continue
            if len(selected) != len(set(selected)):
                _exclude(
                    model,
                    f"case_map_cases_duplicate:{model}",
                    category="model_case_selection",
                    requested=selected,
                    available=available,
                )
                continue
            missing = [case for case in selected if case not in available]
            if missing:
                _exclude(
                    model,
                    f"case_map_cases_missing:{model}:" + ",".join(missing),
                    category="model_case_selection",
                    requested=selected,
                    available=available,
                )
                continue
            effective_map[model] = selected
    else:
        for model in requested_models:
            available = [
                str(value) for value in list(available_case_map.get(model) or [])
                if str(value)
            ]
            if not available:
                _exclude(
                    model,
                    f"discovered_cases_empty:{model}",
                    category="model_native_capability",
                    requested=[],
                    available=available,
                )

    runnable = [model for model in requested_models if model not in exclusions]
    return runnable, effective_map, exclusions, global_errors


def _native_precision_for_backend(
    backend: str,
    configured_precision: str,
) -> str:
    """Resolve the safe production fallback without changing Hailo-8.

    The shared historical profile value ``uint8_cast_fp16`` is still correct
    for Hailo-8.  Hailo-10 now exposes an HEF-native quantized boundary and
    therefore needs the exact scale/zero-point dequant bridge even when a
    row-local Quality binding is unavailable.
    """

    normalized = str(backend or "").strip().lower().replace("-", "_")
    precision = str(configured_precision or "").strip()
    if normalized in {"hailo10", "hailo10h", "hailo10h_to_trt"} and (
        not precision or precision == "uint8_cast_fp16"
    ):
        return "uint8_dequant_fp16"
    return precision or "uint8_cast_fp16"


def _native_model_preflight_rows(
    valid_models: Sequence[str],
    excluded_models: Mapping[str, Any],
    validation_by_model: Mapping[str, Any],
    *,
    energy_requested: bool,
) -> List[Dict[str, Any]]:
    """Describe model-local admission, including per-model Energy skips."""

    rows: List[Dict[str, Any]] = []
    for raw_model, raw_report in sorted(excluded_models.items()):
        model = str(raw_model)
        report = (
            dict(raw_report) if isinstance(raw_report, Mapping)
            else {"detail": raw_report}
        )
        failure_reason = str(
            report.get("failure_reason") or f"benchmark_set_invalid:{model}"
        )
        category = str(report.get("category") or "model_benchmark_set")
        rows.append({
            "model": model,
            "status": "blocked",
            "category": category,
            "preflight_scope": "model",
            "failure_reason": failure_reason,
            "transfer_attempted": False,
            "performance_started": False,
            "energy_started": False,
            "energy_not_started_categories": (
                ["model_preflight"] if energy_requested else []
            ),
            "energy_not_started_reason": (
                "Energy requested, not started: Native preflight "
                f"blocked by {failure_reason}"
                if energy_requested else ""
            ),
            "validation": report,
        })
    for raw_model in valid_models:
        model = str(raw_model)
        rows.append({
            "model": model,
            "status": "ready",
            "category": "model_preflight",
            "preflight_scope": "model",
            "failure_reason": "",
            "transfer_attempted": None,
            "performance_started": None,
            "energy_started": None,
            "energy_not_started_categories": [],
            "energy_not_started_reason": "",
            "validation": validation_by_model.get(model) or {},
        })
    return rows


def _merge_row_local_quality_contracts(
    contracts: Sequence[Mapping[str, Any]],
    *,
    rows_field: str,
    sha_field: str = "",
) -> Dict[str, Any]:
    """Merge independently verified row contracts without widening a row.

    Each input contract has already passed the existing strict selector for a
    single model (or model/case/backend selection).  Combining only those
    successful maps keeps a bad Quality row local while preserving the exact
    fail-closed validation used for every retained row.
    """

    if not contracts:
        raise ValueError("no row-local Quality contract is available")
    merged = dict(contracts[0])
    header_fields = {
        key: value
        for key, value in merged.items()
        if key not in {rows_field, sha_field}
    }
    merged_rows: Dict[str, Any] = {}
    for contract in contracts:
        contract_header = {
            key: value
            for key, value in contract.items()
            if key not in {rows_field, sha_field}
        }
        if contract_header != header_fields:
            raise ValueError(
                "row-local Quality contracts have conflicting contract scope"
            )
        raw_rows = contract.get(rows_field)
        if not isinstance(raw_rows, Mapping) or not raw_rows:
            raise ValueError(f"{rows_field} missing from row-local contract")
        for raw_key, raw_value in raw_rows.items():
            key = str(raw_key)
            if not isinstance(raw_value, Mapping):
                raise ValueError(f"{rows_field}[{key!r}] is not an object")
            value = dict(raw_value)
            if key in merged_rows and merged_rows[key] != value:
                raise ValueError(f"conflicting row-local Quality contract: {key}")
            merged_rows[key] = value
    merged[rows_field] = merged_rows
    if sha_field:
        merged.pop(sha_field, None)
        merged[sha_field] = canonical_contract_sha256(merged)
    return merged


def _native_energy_not_started_projection(
    *,
    requested: bool,
    state: Mapping[str, Any] | None,
) -> Dict[str, Any]:
    """Project one visible, categorized reason when requested Energy did not start.

    This helper is diagnostic only: it neither turns row-local failures into a
    global gate nor weakens the existing global infrastructure/preflight gates.
    """

    if not requested:
        return {}
    payload = dict(state or {}) if isinstance(state, Mapping) else {}
    try:
        started = int(payload.get("started_measurement_count") or 0)
    except (TypeError, ValueError):
        started = 0
    if (
        started > 0
        or payload.get("dry_run") is True
        or str(payload.get("mode") or "").strip().lower() == "plan"
    ):
        return {}

    existing_reason = str(
        payload.get("energy_not_started_reason") or ""
    ).strip()
    existing_categories = [
        str(value).strip()
        for value in list(payload.get("energy_not_started_categories") or [])
        if str(value).strip()
    ]
    if existing_reason:
        return {
            "energy_not_started_categories": existing_categories
            or ["native_energy_preflight"],
            "energy_not_started_reason": existing_reason,
        }

    diagnostics: List[str] = []

    def _add(value: Any) -> None:
        if isinstance(value, Sequence) and not isinstance(
            value, (str, bytes, bytearray),
        ):
            for item in value:
                _add(item)
            return
        if isinstance(value, Mapping):
            for key in (
                "status", "blocked_reason", "failure_reason", "error",
                "errors", "status_detail", "stderr", "stderr_tail",
                "stdout_tail", "preflight", "remote_preflight",
            ):
                _add(value.get(key))
            return
        text = " ".join(str(value or "").split())
        if len(text) > 500:
            text = "…" + text[-499:]
        if text and text not in diagnostics:
            diagnostics.append(text)

    for key in (
        "status", "blocked_reason", "error", "preflight_status",
        "result_status", "result_blocked_reason", "result_error",
        "stderr_tail", "stdout_tail",
    ):
        _add(payload.get(key))
    _add(payload.get("plan_preflight"))
    _add(payload.get("preflight"))
    _add(payload.get("backend_results"))
    _add(payload.get("central_binding_preflight"))
    diagnostic_text = " ".join(diagnostics).lower()

    categories: List[str] = []

    def _category(name: str) -> None:
        if name not in categories:
            categories.append(name)

    if any(token in diagnostic_text for token in (
        "generic_energy", "energy configuration", "measurement_path",
    )):
        _category("energy_configuration")
    if any(token in diagnostic_text for token in (
        "calibration", "manifest", "hardware_setups", "global config",
        "physical_scope", "window_label",
    )):
        _category("global_energy_configuration")
    if any(token in diagnostic_text for token in (
        "u.recs", "urecs", "collector", "acquisition",
    )):
        _category("collector_initialization")
    if any(token in diagnostic_text for token in (
        "platform lock", "platform_lock", "lock busy", "lock unavailable",
    )):
        _category("platform_lock")
    if any(token in diagnostic_text for token in (
        "ssh", "authentication", "permission denied", "publickey",
        "host unreachable", "network is unreachable", "connection refused",
        "connection timed out",
    )):
        _category("global_remote_infrastructure")
    if any(token in diagnostic_text for token in (
        "benchmark_set_invalid", "model preflight", "model_preflight",
    )):
        _category("model_preflight")
    if any(token in diagnostic_text for token in (
        "technical_quality", "quality contract", "quality_contract",
        "preprocessing_contract",
    )):
        _category("technical_quality_no_runtime_rows")
    if any(token in diagnostic_text for token in (
        "preflight", "no_runnable", "no complete", "no_complete",
        "no_runtime_constructible",
    )):
        _category("native_runtime_preflight")
    remote_counter_declared = any(
        key in payload
        for key in ("started_remote_count", "started_performance_count")
    )
    if remote_counter_declared:
        try:
            remote_started = int(payload.get("started_remote_count") or 0)
            performance_started = int(
                payload.get("started_performance_count") or 0
            )
        except (TypeError, ValueError):
            remote_started = performance_started = 0
        if remote_started == 0 and performance_started == 0:
            _category("no_remote_or_native_start")
    if not categories:
        _category("native_energy_infrastructure")

    detail = (
        "; ".join(diagnostics[:8]) or "no measurement was started"
    )[:1600]
    reason = (
        "Energy requested, not started: Native preflight blocked by "
        + ",".join(categories)
        + ": "
        + detail
    )
    return {
        "energy_not_started_categories": categories,
        "energy_not_started_reason": reason,
    }


def _native_backend_start_counts(
    backend_results: Sequence[Mapping[str, Any]],
) -> Dict[str, int]:
    """Aggregate workload-launch counters recorded by backend dispatch."""

    return {
        "started_remote_count": sum(
            int(row.get("started_remote_count") or 0)
            for row in backend_results if isinstance(row, Mapping)
        ),
        "started_performance_count": sum(
            int(row.get("started_performance_count") or 0)
            for row in backend_results if isinstance(row, Mapping)
        ),
    }


def _native_remote_launch_observed(result: Any) -> bool:
    """Count only a workload whose remote command crossed the SSH boundary."""

    try:
        returncode = int(getattr(result, "returncode"))
    except (AttributeError, TypeError, ValueError):
        return False
    if returncode == 0:
        return True
    text = "\n".join((
        str(getattr(result, "stdout", "") or ""),
        str(getattr(result, "stderr", "") or ""),
    )).lower()
    # A non-zero workload may still have started and then failed.  Count it
    # only when the remote runner emitted one of its execution markers;
    # SSH/auth/connect failures never emit these markers.
    # Full.main handles backend exceptions and returns 3 without a traceback.
    # Its repetition marker proves that a runtime attempt began; the earlier
    # "preparing exact Full input" and interpreter messages do not.
    full_repetition_started = re.search(
        r"(?m)^\[native-full\] \S+/\S+ repetition=[1-9]\d*/[1-9]\d*[ \t]*$",
        text,
    ) is not None
    return full_repetition_started or any(marker in text for marker in (
        "[native-progress]", "[producer-e2e-eval]", "[native-fifo]",
        "hailo10_native_fifo_e2e", "deepx_native_fifo_e2e",
        "native_full_baseline_eval_runner",
    ))


def _native_global_infrastructure_failure(*values: Any) -> str:
    """Classify only failures that invalidate every remaining remote row."""

    text = "\n".join(str(value or "") for value in values).lower()
    if not text.strip():
        return ""
    if any(token in text for token in (
        "permission denied", "authentication failed", "publickey",
        "host key verification failed",
    )):
        return "remote_authentication_failed"
    if any(token in text for token in (
        "connection refused", "connection timed out", "no route to host",
        "network is unreachable", "could not resolve hostname",
    )):
        return "remote_connection_failed"
    if any(token in text for token in (
        "platform_lock unavailable", "platform lock unavailable",
        "platform_lock busy", "platform lock busy",
    )):
        return "platform_lock_unavailable"
    return ""


def _native_split_requires_single_part2_input_v270k(
    native_config: Mapping[str, Any] | None,
) -> bool:
    """Return the current Native FIFO boundary capability.

    Native Full does not use a split boundary.  Only a selected
    Hailo/DeepX-to-TensorRT adapter requires exactly one Part-2 external input.
    """
    cfg = native_config if isinstance(native_config, Mapping) else {}
    if "split_backends" in cfg:
        raw = cfg.get("split_backends")
        if isinstance(raw, str):
            return bool(raw.strip())
        if isinstance(raw, Sequence) and not isinstance(
            raw, (bytes, bytearray)
        ):
            return any(str(value or "").strip() for value in raw)
        return False
    # Compatibility for callers supplying a pre-logical-matrix Native block.
    return bool(
        cfg.get("enabled")
        or cfg.get("run")
        or cfg.get("enabled_in_evalrun")
    )


def _native_split_case_support_v270e(
    benchmark_sets: Mapping[str, Path],
    selected_case_map: Mapping[str, Sequence[str]],
) -> list[dict[str, Any]]:
    """Classify selected split cases against the current Native FIFO boundary.

    Generic execution supports multiple Part-2 inputs.  The three physical
    Native producer adapters currently hand exactly one accelerator boundary
    tensor to TensorRT, so their plan must exclude multi-input cases explicitly
    instead of either hiding them behind a fixed smoke whitelist or starting a
    runner that will reject them later.
    """

    rows: list[dict[str, Any]] = []
    for model, raw_cases in selected_case_map.items():
        benchmark_set = Path(benchmark_sets.get(model) or "")
        seen: set[str] = set()
        for raw_case in raw_cases:
            case = str(raw_case or "").strip()
            if not case or case in seen:
                continue
            seen.add(case)
            manifest_path = benchmark_set / case / "split_manifest.json"
            names: list[str] = []
            reason = ""
            try:
                payload = json.loads(manifest_path.read_text(encoding="utf-8"))
                declared = payload.get("part2_external_inputs")
                if (
                    not isinstance(payload, Mapping)
                    or not isinstance(declared, list)
                    or any(not str(name or "").strip() for name in declared)
                ):
                    raise ValueError("part2_external_inputs_invalid")
                names = [str(name).strip() for name in declared]
            except Exception as exc:
                reason = (
                    "split_manifest_part2_inputs_unavailable:"
                    + type(exc).__name__
                )
            count = len(names) if not reason else None
            supported = count == 1
            if not reason and not supported:
                reason = "part2_input_count_not_one"
            rows.append({
                "model": str(model),
                "case": case,
                "split_manifest": str(manifest_path),
                "part2_input_count": count,
                "part2_input_names": names,
                "native_supported": supported,
                "status": "eligible" if supported else "capability_excluded",
                "reason": "exactly_one_part2_input" if supported else reason,
            })
    return rows


def _native_model_family_task_v27919(value: Any) -> tuple[str, str]:
    """Return the explicit Native model family/task, or empty values.

    Keep orchestration aligned with ``known_native_split_policy`` without
    treating every unknown non-ResNet model as detection.
    """

    token = str(value or "").strip().lower()
    for family in ("resnet", "mobilenet", "regnet"):
        if token.startswith(family):
            return family, "classification"
    if token.startswith("yolo"):
        return "yolo", "detection"
    return "", ""


def _native_selection_contract_runs_v270e(
    backend: str,
    supported_case_map: Mapping[str, Sequence[str]],
) -> list[dict[str, Any]]:
    """Build model-family runtime contracts without narrowing case selection."""

    normalized_backend = str(backend or "").strip().lower()
    runs: list[dict[str, Any]] = []
    for model, raw_cases in supported_case_map.items():
        cases = [
            str(case).strip()
            for case in raw_cases
            if str(case or "").strip()
        ]
        if not cases:
            continue
        model_token = str(model or "").strip().lower()
        model_family, task = _native_model_family_task_v27919(model_token)
        if task == "classification":
            preprocess = "resize"
            pad = 0
        elif task == "detection":
            preprocess = "letterbox"
            pad = 114
        else:
            continue

        contract: dict[str, Any] = {
            "id": (
                f"{normalized_backend}_{model_token}_selected_"
                "single_part2_input"
            ),
            "models": [str(model)],
            "case_map": {str(model): cases},
            "task": task,
            "model_family": model_family,
            "preprocess_mode": "auto",
            "preprocess_mode_effective": preprocess,
            "letterbox_pad_value": 114,
            "letterbox_pad_value_effective": pad,
            "selection_source": "effective_deployment_selection",
            "capability_contract": "exactly_one_part2_external_input",
        }
        if normalized_backend == "hailo8":
            contract.update({
                "precision": (
                    "float32_layout_fp16"
                    if task == "classification"
                    else "uint8_dequant_fp16"
                ),
                "hailo_format": (
                    "float32" if task == "classification" else "uint8"
                ),
                "boundary_layout": "memory_nhwc_to_nchw",
            })
        elif normalized_backend == "hailo10h":
            contract.update({
                "precision": "uint8_dequant_fp16",
                "hailo_format": "uint8",
                "boundary_layout": "memory_nhwc_to_nchw",
            })
        elif normalized_backend == "deepx":
            contract.update({
                "precision": "float32_layout_fp16",
                "boundary_layout": "as_input",
            })
        else:
            continue
        runs.append(contract)
    return runs


def _quality_execution_location_v263(profile: Mapping[str, Any] | None) -> str:
    payload = dict(profile or {})
    quality = payload.get("quality_gate") if isinstance(payload.get("quality_gate"), Mapping) else {}
    statistics = quality.get("statistics") if isinstance(quality.get("statistics"), Mapping) else {}
    execution = quality.get("execution") if isinstance(quality.get("execution"), Mapping) else {}
    value = str(
        statistics.get("execution_location")
        or quality.get("execution_location")
        or execution.get("location")
        or "local"
    ).strip().lower().replace("-", "_")
    if value in {"management", "management_node", "central", "central_cpu"}:
        return "central_management"
    return value if value in {"local", "central_management"} else "local"


def _quality_workers_v263(profile: Mapping[str, Any] | None) -> int:
    payload = dict(profile or {})
    quality = payload.get("quality_gate") if isinstance(payload.get("quality_gate"), Mapping) else {}
    statistics = quality.get("statistics") if isinstance(quality.get("statistics"), Mapping) else {}
    try:
        return max(1, min(64, int(statistics.get("workers") or 4)))
    except (TypeError, ValueError):
        return 4


def _full_only_quality_profile_context_v27538(
    profile: Mapping[str, Any] | None,
) -> bool:
    """Return whether the active profile authorizes a Quality-only plan.

    Row-local markers are not an authority for changing matrix cardinality.
    The exception applies only to the explicit Full-only Canary running its
    quality service on central management.
    """

    payload = dict(profile or {}) if isinstance(profile, Mapping) else {}
    canary = (
        dict(payload.get("quality_canary") or {})
        if isinstance(payload.get("quality_canary"), Mapping) else {}
    )
    return bool(
        canary.get("enabled") is True
        and str(canary.get("execution_scope") or "").strip().lower()
        == "full_only"
        and _quality_execution_location_v263(payload) == "central_management"
    )


def _performance_plan_v263(
    benchmark_plan: Mapping[str, Any], profile: Mapping[str, Any] | None
) -> dict[str, Any]:
    """Remove non-performance rows from performance accounting.

    Full-only Quality Canary rows execute a dataset and emit Central Quality
    requests, but deliberately do not emit Generic/performance measurements.
    Keeping those projected rows in the performance plan made a successful
    quality-only dispatch look like two missing benchmark result files.  Their
    explicit contract is retained separately for audit, while ordinary rows
    (including rows with incomplete/ambiguous markers) remain fail-closed.
    """
    plan = dict(benchmark_plan or {})
    source_runs = list(plan.get("runs") or plan.get("planned_runs") or [])
    kept: list[Any] = []
    excluded: list[str] = []
    quality_only_runs: list[dict[str, Any]] = []
    central_management = (
        _quality_execution_location_v263(profile) == "central_management"
    )
    quality_only_context = _full_only_quality_profile_context_v27538(profile)
    previously_sealed_quality_runs = _quality_only_runs_v27538(plan)
    if not quality_only_context:
        # A previously projected plan cannot remain N/A after its authorizing
        # profile context disappears.  Restore the sealed rows so ordinary
        # completeness checks fail closed instead of accepting an empty plan.
        known_ids = {
            str(
                (row.get("id") or row.get("run_id"))
                if isinstance(row, Mapping) else row
            ).strip()
            for row in source_runs
        }
        source_runs.extend(
            row for row in previously_sealed_quality_runs
            if str(row.get("id") or row.get("run_id") or "").strip()
            not in known_ids
        )
    cpu_aliases = {"cpu", "cpu_ort", "ort_cpu", "onnxruntime_cpu", "cpu_onnxruntime"}
    for raw in source_runs:
        run_id = str((raw.get("id") or raw.get("run_id")) if isinstance(raw, Mapping) else raw).strip()
        if (
            quality_only_context
            and isinstance(raw, Mapping)
            and _is_full_only_quality_run_v27538(raw)
        ):
            excluded.append(run_id)
            quality_only_runs.append(dict(raw))
            continue
        token = run_id.lower().replace("-", "_")
        cpu_reference = bool(central_management and token in cpu_aliases)
        if isinstance(raw, Mapping):
            cpu_reference = cpu_reference or bool(central_management and any(
                str(raw.get(key) or "").strip().lower().replace("-", "_") in cpu_aliases
                for key in ("backend", "provider", "execution_provider", "device", "runtime")
            )) or bool(
                central_management
                and (
                    raw.get("semantic_reference_only")
                    or raw.get("canonical_cpu_reference")
                )
            )
        if cpu_reference:
            excluded.append(run_id)
            continue
        kept.append(raw)
    if quality_only_context:
        known_quality_ids = {
            str(row.get("id") or row.get("run_id") or "").strip()
            for row in quality_only_runs
        }
        quality_only_runs.extend(
            row for row in previously_sealed_quality_runs
            if str(row.get("id") or row.get("run_id") or "").strip()
            not in known_quality_ids
        )
    if "runs" in plan or "planned_runs" not in plan:
        plan["runs"] = kept
    if "planned_runs" in plan:
        plan["planned_runs"] = kept
    semantic_reference_ids = [
        rid for rid in excluded
        if rid not in {
            str(row.get("id") or row.get("run_id") or "")
            for row in quality_only_runs
        }
    ]
    plan["semantic_reference_run_ids"] = semantic_reference_ids
    plan["performance_excluded_run_ids"] = excluded
    projection = _quality_only_projection_v27538(quality_only_runs)
    plan["quality_only_projection"] = projection if quality_only_context else {}
    plan["quality_only_runs"] = quality_only_runs if quality_only_context else []
    plan["quality_only_run_ids"] = [
        str(row.get("id") or row.get("run_id") or "")
        for row in quality_only_runs
    ]
    actionable_kept = [
        row for row in kept
        if not isinstance(row, Mapping)
        or not bool(row.get("deferred")) and row.get("required") is not False
    ]
    quality_only_not_applicable = bool(quality_only_runs) and not actionable_kept
    plan["performance_matrix_applicable"] = not quality_only_not_applicable
    plan["performance_matrix_status"] = (
        "not_applicable_quality_evidence_only"
        if quality_only_not_applicable else "applicable"
    )
    if central_management:
        plan["cpu_reference_execution_location"] = "central_management"
    return plan


def _candidate_case_id_v261e(row: Mapping[str, Any], index: int = 0) -> str:
    """Return the canonical case ID used to join plans and measured rows."""
    case_id = str(row.get("case_id") or row.get("case") or "").strip()
    if case_id:
        return case_id
    boundary = row.get("boundary", row.get("split_index", row.get("boundary_index")))
    try:
        return f"b{int(float(str(boundary))):03d}"
    except Exception:
        return f"candidate_{index:04d}" if index else ""


def _annotate_candidate_execution_contract_v261e(
    rows: Sequence[Mapping[str, Any]],
    candidate_plan: Mapping[str, Any],
) -> list[dict[str, Any]]:
    """Bind audit/deployment roles from the immutable plan to result rows.

    Runtime result files are allowed to contain only their traditional case ID.
    The formal candidate plan is authoritative for the methodological role of
    that case.  Joining here keeps the score-independent audit distinguishable
    from an overlapping predictor-selected deployment shortlist all the way to
    ``normalized_results.json`` and the scientific reporter.
    """
    by_case: dict[str, dict[str, Any]] = {}
    ambiguous_cases: set[str] = set()
    for index, source in enumerate(list(candidate_plan.get("selected_candidates") or []), start=1):
        if not isinstance(source, Mapping):
            continue
        candidate = dict(source)
        case_id = _candidate_case_id_v261e(candidate, index)
        if case_id:
            if case_id in by_case and by_case[case_id] != candidate:
                ambiguous_cases.add(case_id)
            else:
                by_case[case_id] = candidate

    annotated: list[dict[str, Any]] = []
    # The plan freezes the graph-boundary identity.  It cannot freeze an
    # execution identity because backend, setup, precision and interface
    # contract are properties of each subsequently measured result row.
    transferable = (
        "candidate_id",
        "candidate_identity_sha256",
        "audit_rank",
        "deployment_rank",
        "prediction_rank",
        "rank",
        "source_rank",
        "predicted_total_latency_ms",
        "predicted_transfer_latency_ms",
        "predicted_stream_cycle_ms",
        "predicted_stream_cycle_ms_calibrated",
        "predicted_stream_fps",
        "predicted_stream_fps_calibrated",
        "predicted_handover_ms",
        "predicted_handover_ms_calibrated",
        "predicted_hailo_feasible",
        "prediction_score",
        "score_pred",
        "accelerator_fit_score",
        "objective_balanced_score",
    )
    for source in rows:
        row = dict(source)
        case_id = _candidate_case_id_v261e(row)
        candidate = None if case_id in ambiguous_cases else by_case.get(case_id)
        is_split = str(row.get("variant") or "").strip().lower() == "split"
        if case_id in ambiguous_cases:
            row["candidate_plan_join_status"] = "ambiguous_case_id"
            row["candidate_plan_join_complete"] = False
        elif candidate is None and is_split:
            row["candidate_plan_join_status"] = "candidate_missing"
            row["candidate_plan_join_complete"] = False
        elif candidate is None:
            row["candidate_plan_join_status"] = "not_applicable_full_baseline"
            row["candidate_plan_join_complete"] = True
        if candidate is not None:
            row["candidate_plan_join_status"] = "joined"
            row["candidate_plan_join_complete"] = True
            roles = candidate.get("candidate_execution_roles")
            if isinstance(roles, str):
                roles = [part.strip() for part in roles.replace(";", ",").split(",") if part.strip()]
            elif isinstance(roles, Sequence) and not isinstance(roles, (bytes, bytearray, str)):
                roles = [str(part).strip() for part in roles if str(part).strip()]
            else:
                roles = []
            roles = sorted(set(roles))
            row["candidate_execution_roles"] = roles
            row["selected_for_score_independent_audit"] = "audit" in roles
            row["selected_for_deployment_shortlist"] = "deployment_shortlist" in roles
            row["candidate_plan_artifact_id"] = str(candidate_plan.get("artifact_id") or "")
            row["candidate_universe_sha256"] = str(candidate_plan.get("candidate_universe_sha256") or "")
            for field in transferable:
                if candidate.get(field) not in (None, ""):
                    row[field] = candidate.get(field)

            # Canonical aliases make the prospective values directly
            # available to normalization/reporting without consulting a
            # second file.  The frozen candidate remains authoritative.
            if row.get("prediction_rank") in (None, ""):
                row["prediction_rank"] = candidate.get("source_rank", candidate.get("rank"))
            if row.get("prediction_score") in (None, ""):
                row["prediction_score"] = candidate.get(
                    "score_pred",
                    candidate.get("accelerator_fit_score", candidate.get("objective_balanced_score")),
                )
            if row.get("predicted_cycle_ms") in (None, ""):
                row["predicted_cycle_ms"] = candidate.get(
                    "predicted_stream_cycle_ms_calibrated",
                    candidate.get("predicted_stream_cycle_ms", candidate.get("predicted_total_latency_ms")),
                )
            if row.get("predicted_fps") in (None, ""):
                row["predicted_fps"] = candidate.get(
                    "predicted_stream_fps_calibrated",
                    candidate.get("predicted_stream_fps"),
                )

            candidate_id = str(row.get("candidate_id") or "").strip()
            core_digest = str(row.get("candidate_identity_sha256") or "").strip()
            if candidate_id and core_digest:
                direction = str(row.get("direction") or row.get("pipeline_direction") or "").strip()
                if not direction:
                    stage1 = str(row.get("stage1_backend") or row.get("producer_backend") or "").strip()
                    stage2 = str(row.get("stage2_backend") or row.get("consumer_backend") or "").strip()
                    if stage1 and stage2:
                        direction = f"{stage1}_to_{stage2}"
                    else:
                        run_id = str(row.get("run_id") or "").strip()
                        if "_to_" in run_id:
                            direction = run_id
                stratum = {
                    "direction": direction,
                    "runner_regime": str(row.get("runner_regime") or row.get("runner") or "").strip(),
                    "setup_id": str(row.get("setup_id") or row.get("hardware_setup_id") or row.get("setup") or "").strip(),
                    "backend": str(row.get("backend") or row.get("producer_backend") or "").strip(),
                    "precision": str(row.get("precision") or row.get("dtype") or "").strip(),
                    "contract_id": str(row.get("contract_id") or row.get("contract") or "").strip(),
                    "contract_sha256": str(
                        row.get("contract_sha256")
                        or row.get("contract_hash")
                        or row.get("interface_contract_hash")
                        or row.get("pipeline_contract_sha256")
                        or ""
                    ).strip(),
                }
                execution_payload = {
                    "candidate_core_sha256": core_digest,
                    **{key: value for key, value in stratum.items() if value},
                }
                execution_digest = sha256_json(execution_payload)
                row["execution_candidate_identity_sha256"] = execution_digest
                row["execution_candidate_id"] = (
                    f"{candidate_id}::{execution_digest.replace('sha256:', '')[:16]}"
                )
                row["candidate_execution_identity_source"] = (
                    "normalized_result_plus_frozen_candidate_core"
                )
        annotated.append(row)
    return annotated


def _campaign_stage_status_v60p(status: Any) -> str:
    """Map campaign readiness to the workflow/job-tree severity.

    Final-only prerequisites are deliberately deferred in Smoke/Standard runs.
    A development-ready campaign is therefore healthy, not a warning.
    """
    state = str(status or "incomplete").strip().lower()
    return "ok" if state in {"ready", "final_ready", "development_ready", "screening_ready"} else "warn"


def _benchmark_stage_status_v60p(
    *,
    normalized_row_count: int,
    executor_status: Any,
    executor_metrics: Optional[Mapping[str, Any]] = None,
) -> str:
    """Keep partial remote matrices visible even when some rows arrived."""
    metrics = dict(executor_metrics or {})
    state = str(executor_status or "").strip().lower()
    incomplete = (
        state in {"partial", "failed", "warn", "warning", "timeout", "timed_out"}
        or bool(metrics.get("remote_pending"))
        or bool(metrics.get("remote_dispatch_failed"))
        or bool(metrics.get("timed_out"))
        or int(metrics.get("selected_run_missing_count") or 0) > 0
    )
    if int(normalized_row_count or 0) > 0:
        return "partial" if incomplete else "ok"
    if incomplete or bool(metrics.get("dispatched")) or bool(metrics.get("remote_dispatched")):
        return "partial"
    return "skipped"


def _is_full_baseline_run_v60r(run: Mapping[str, Any]) -> bool:
    """Return whether a selected plan row is a full-model baseline.

    The generated benchmark plan uses short run IDs (``hailo8``,
    ``ort_tensorrt``) for full baselines and ``*_to_*`` IDs for split rows.
    Type/stage checks keep imported plans compatible with that convention.
    """
    rid = str(run.get("id") or run.get("run_id") or "").strip().lower().replace("-", "_")
    if not rid:
        return False
    if "_to_" in rid or rid.endswith("_split") or rid.startswith("split_"):
        return False
    if rid in {
        "ort_cpu", "ort_cuda", "ort_tensorrt", "tensorrt",
        "hailo8", "hailo8l", "hailo8r", "hailo10", "hailo10h", "hailo10p",
        "deepx", "deepx_m1", "deepx_m1_full",
    } or rid.endswith("_full"):
        return True
    typ = str(run.get("type") or "").strip().lower().replace("-", "_")
    if typ not in {"onnxruntime", "hailo", "deepx", "full", "full_model"}:
        return False
    stage1 = run.get("stage1") if isinstance(run.get("stage1"), Mapping) else {}
    stage2 = run.get("stage2") if isinstance(run.get("stage2"), Mapping) else {}
    def _stage_token(stage: Mapping[str, Any]) -> str:
        return str(stage.get("backend") or stage.get("provider") or stage.get("hw_arch") or stage.get("type") or "").strip().lower().replace("-", "_")
    left, right = _stage_token(stage1), _stage_token(stage2)
    return bool(left and right and left == right) or typ in {"full", "full_model"}


def _is_full_only_quality_run_v27538(run: Mapping[str, Any]) -> bool:
    """Recognize only the explicit, non-performance Full-only projection.

    A single loose flag is intentionally insufficient.  This keeps normal
    Standard/Performance plans fail-closed if a producer accidentally writes a
    quality-looking field.  A projected row must carry the complete canonical
    scope, role and non-performance contract as well as the explicit projection
    marker, and it must be restricted to the Full variant/case.
    """

    scope = str(run.get("execution_scope") or "").strip().lower()
    role = str(run.get("execution_role") or "").strip().lower()
    explicit_contract = bool(
        scope == "full_only"
        and role == "full_quality_only"
        and run.get("performance_claims_emitted") is False
        and run.get("quality_evidence_only") is True
    )
    if not explicit_contract:
        return False

    variant = str(run.get("variant") or "").strip().lower()
    variants_value = run.get("variants")
    if not (
        isinstance(variants_value, Sequence)
        and not isinstance(variants_value, (str, bytes, bytearray))
    ):
        return False
    variants = [
        str(value or "").strip().lower()
        for value in variants_value
    ]
    if variant != "full" or not variants or any(
        value != "full" for value in variants
    ):
        return False
    case_id = str(run.get("case_id") or "").strip().lower()
    return case_id == "full"


def _quality_only_projection_v27538(
    rows: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Seal the exact rows excluded by the active profile projection."""

    quality_rows = [
        dict(row) for row in rows
        if isinstance(row, Mapping) and _is_full_only_quality_run_v27538(row)
    ]
    payload = {
        "schema": "onnx-splitpoint/full-only-performance-projection",
        "schema_version": 1,
        "active": bool(quality_rows),
        "execution_scope": "full_only",
        "quality_execution_location": "central_management",
        "quality_only_runs": quality_rows,
    }
    return {
        **payload,
        "projection_sha256": sha256_json(payload),
    }


def _quality_only_runs_v27538(
    benchmark_plan: Mapping[str, Any] | None,
) -> list[dict[str, Any]]:
    """Return unique quality-only rows, including rows already projected out."""

    plan = dict(benchmark_plan or {})
    projection = (
        dict(plan.get("quality_only_projection") or {})
        if isinstance(plan.get("quality_only_projection"), Mapping) else {}
    )
    projection_sha = str(projection.pop("projection_sha256", "") or "")
    if (
        projection.get("schema")
        != "onnx-splitpoint/full-only-performance-projection"
        or int(projection.get("schema_version") or 0) != 1
        or projection.get("active") is not True
        or str(projection.get("execution_scope") or "").strip().lower()
        != "full_only"
        or str(
            projection.get("quality_execution_location") or ""
        ).strip().lower() != "central_management"
        or not projection_sha
        or projection_sha != sha256_json(projection)
    ):
        return []
    candidates = list(projection.get("quality_only_runs") or [])
    legacy_rows = list(plan.get("quality_only_runs") or [])
    if legacy_rows != candidates:
        return []
    out: list[dict[str, Any]] = []
    seen: set[str] = set()
    for raw in candidates:
        if not isinstance(raw, Mapping) or not _is_full_only_quality_run_v27538(raw):
            continue
        row = dict(raw)
        run_id = str(row.get("id") or row.get("run_id") or "").strip()
        identity = run_id or sha256_json(row)
        if identity in seen:
            continue
        seen.add(identity)
        out.append(row)
    return out


def _sealed_quality_only_identity_v27538(
    run: Mapping[str, Any],
    benchmark_plan: Mapping[str, Any] | None,
) -> bool:
    """Require membership in the validated projection, not row-local flags."""

    identity = sha256_json(dict(run))
    return identity in {
        sha256_json(dict(row))
        for row in _quality_only_runs_v27538(benchmark_plan)
    }


def _selected_run_completeness_v60r(
    *,
    benchmark_plan: Mapping[str, Any],
    source_records: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Reconcile every selected plan run with a non-empty primary result.

    A remote dispatch can finish successfully while a selected backend emits an
    empty ``benchmark_results_<run>_auto.json`` (for example after a full-model
    compiler timeout).  Normalized rows from the other backends must not hide
    that gap.  Failure/unsupported rows still count as evidence when the primary
    result file is non-empty; only missing or empty primary files make the
    requested matrix incomplete.
    """
    runs = list(benchmark_plan.get("runs") or benchmark_plan.get("planned_runs") or [])
    all_selected = [dict(row) for row in runs if isinstance(row, Mapping) and str(row.get("id") or row.get("run_id") or "").strip()]
    quality_only = _quality_only_runs_v27538(benchmark_plan)
    quality_only_ids = {
        str(row.get("id") or row.get("run_id") or "").strip()
        for row in quality_only
    }
    non_quality_selected = [
        row for row in all_selected
        if not _sealed_quality_only_identity_v27538(row, benchmark_plan)
    ]
    deferred = [
        row for row in non_quality_selected
        if bool(row.get("deferred")) or row.get("required") is False
    ]
    expected = [row for row in non_quality_selected if row not in deferred]
    performance_matrix_applicable = not bool(
        quality_only
        and not expected
        and not non_quality_selected
    )

    primary_by_tag: dict[str, dict[str, Any]] = {}
    for source in source_records:
        path = Path(str(source.get("path") or ""))
        if not path.name.startswith("benchmark_results_"):
            continue
        tag = str(source.get("tag") or "").strip().lower().replace("-", "_")
        if not tag:
            continue
        row_count = int(source.get("row_count") or 0)
        current = primary_by_tag.get(tag)
        record = {
            "path": str(path),
            "tag": tag,
            "row_count": row_count,
            "suffix": path.suffix.lower(),
        }
        # Prefer a non-empty JSON source, then any non-empty source.
        score = (1 if row_count > 0 else 0, 1 if path.suffix.lower() == ".json" else 0)
        current_score = (
            1 if current and int(current.get("row_count") or 0) > 0 else 0,
            1 if current and str(current.get("suffix") or "") == ".json" else 0,
        )
        if current is None or score > current_score:
            primary_by_tag[tag] = record

    rows: list[dict[str, Any]] = []
    missing_ids: list[str] = []
    missing_full: list[str] = []
    for run in expected:
        rid = str(run.get("id") or run.get("run_id") or "").strip()
        rid_norm = rid.lower().replace("-", "_")
        candidates = [rid_norm + "_auto", rid_norm]
        source = next((primary_by_tag[tag] for tag in candidates if tag in primary_by_tag), None)
        row_count = int((source or {}).get("row_count") or 0)
        present = bool(source and row_count > 0)
        full_baseline = _is_full_baseline_run_v60r(run)
        reason = "measured_result_present" if present else ("empty_primary_result" if source else "primary_result_missing")
        item = {
            "run_id": rid,
            "run_type": str(run.get("type") or ""),
            "full_baseline": bool(full_baseline),
            "complete": bool(present),
            "reason": reason,
            "primary_result_path": str((source or {}).get("path") or ""),
            "primary_result_row_count": row_count,
        }
        rows.append(item)
        if not present:
            missing_ids.append(rid)
            if full_baseline:
                missing_full.append(rid)

    matrix_complete: bool | None = (
        None
        if not performance_matrix_applicable
        else bool(expected) and not missing_ids
    )
    return {
        "schema": "onnx-splitpoint/selected-run-completeness",
        "schema_version": 1,
        "selected_run_count": len(all_selected) or len(quality_only),
        "expected_run_count": len(expected),
        "deferred_run_count": len(deferred),
        "deferred_runs": deferred,
        "quality_only_run_count": len(quality_only),
        "quality_only_run_ids": sorted(quality_only_ids),
        "quality_only_runs": quality_only,
        "performance_matrix_applicable": performance_matrix_applicable,
        "performance_matrix_status": (
            "applicable"
            if performance_matrix_applicable
            else "not_applicable_quality_evidence_only"
        ),
        "complete_run_count": len(expected) - len(missing_ids),
        "missing_run_count": len(missing_ids),
        "matrix_complete": matrix_complete,
        "missing_selected_run_ids": missing_ids,
        "missing_full_baseline_run_ids": missing_full,
        "runs": rows,
    }


def _sealed_full_only_quality_normalized_contract_v27538(
    payload: Mapping[str, Any] | None,
) -> bool:
    """Recognize the exact rowless Full-only Quality terminal contract.

    Aggregate reporting normally treats zero benchmark rows as pending.  The
    only exception is the explicit non-performance projection whose Central
    Quality evidence completed exactly.  Keep this predicate deliberately
    independent from row-local quality flags so malformed or ordinary empty
    benchmark payloads continue to fail closed.
    """

    contract = dict(payload or {})
    rows = contract.get("results")
    if not (
        isinstance(rows, Sequence)
        and not isinstance(rows, (str, bytes, bytearray))
        and not rows
    ):
        return False

    def _exact_int(key: str) -> int | None:
        value = contract.get(key)
        if isinstance(value, bool):
            return None
        if isinstance(value, int):
            return value
        if isinstance(value, str) and re.fullmatch(r"[+-]?\d+", value.strip()):
            return int(value.strip())
        return None

    result_count = _exact_int("result_count")
    evidence_count = _exact_int("quality_evidence_count")
    expected_count = _exact_int("expected_full_quality_count")
    return bool(
        str(contract.get("status") or "").strip().lower()
        == "quality_evidence_only_complete"
        and contract.get("performance_matrix_applicable") is False
        and contract.get("quality_evidence_only_complete") is True
        and contract.get("matrix_complete") is True
        and result_count == 0
        and expected_count is not None
        and expected_count > 0
        and evidence_count == expected_count
    )




def _canonical_backend_v60r(value: Any) -> str:
    token = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "ort_cpu": "cpu_ort", "cpu": "cpu_ort", "ort_tensorrt": "tensorrt", "trt": "tensorrt",
        "hailo10h": "hailo10", "hailo_10": "hailo10", "hailo_8": "hailo8",
        "deepx": "deepx_m1", "deepx_to_tensorrt": "deepx_m1_to_tensorrt",
        "hailo8_to_trt": "hailo8_to_tensorrt", "hailo10_to_trt": "hailo10_to_tensorrt",
        "trt_to_hailo8": "tensorrt_to_hailo8", "trt_to_hailo10": "tensorrt_to_hailo10",
        "trt_to_deepx": "tensorrt_to_deepx_m1", "tensorrt_to_deepx": "tensorrt_to_deepx_m1",
    }
    return aliases.get(token, token)


def _canonical_benchmark_case_id_v27919(row: Any) -> str:
    """Resolve every established BenchmarkSet case representation."""

    if isinstance(row, Mapping):
        case_id = str(
            row.get("id")
            or row.get("case_id")
            or row.get("case")
            or row.get("case_dir")
            or row.get("folder")
            or ""
        ).strip()
        if not case_id:
            boundary = row.get(
                "boundary",
                row.get("split_index", row.get("boundary_index")),
            )
            try:
                case_id = f"b{int(boundary):03d}"
            except (TypeError, ValueError):
                return ""
    else:
        case_id = str(row or "").strip()
    if case_id.isdigit():
        return f"b{int(case_id):03d}"
    return case_id


def _benchmark_case_ids_v60r(benchmark_set_contract: Mapping[str, Any] | None) -> list[str]:
    out: list[str] = []
    for row in list((benchmark_set_contract or {}).get("cases") or []):
        case_id = _canonical_benchmark_case_id_v27919(row)
        if not case_id:
            continue
        if case_id not in out:
            out.append(case_id)
    return out


def expected_profile_measurements_v60r(*, model_id: str, benchmark_plan: Mapping[str, Any] | None, benchmark_set_contract: Mapping[str, Any] | None) -> list[dict[str, Any]]:
    """Actionable result rows implied by the selected logical hardware paths."""
    case_ids = _benchmark_case_ids_v60r(benchmark_set_contract)
    runs = [r for r in list((benchmark_plan or {}).get("runs") or []) if isinstance(r, Mapping)]
    out: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()

    def add(
        backend: str, variant: str, case_id: str = "full",
        run_id: str = "", run: Mapping[str, Any] | None = None,
    ) -> None:
        backend_n = _canonical_backend_v60r(backend)
        variant_n = str(variant).lower()
        key = (backend_n, variant_n, str(case_id) if variant_n == "split" else "full")
        if key in seen:
            return
        seen.add(key)
        run = run or {}
        descriptor: Mapping[str, Any] = {}
        for candidate in list(run.get("physical_identity_descriptors") or []):
            if not isinstance(candidate, Mapping):
                continue
            candidate_model = str(candidate.get("model_id") or "").strip()
            if candidate_model and candidate_model != str(model_id):
                continue
            if (
                _canonical_backend_v60r(candidate.get("backend")) == backend_n
                and str(candidate.get("variant") or "").strip().lower()
                == variant_n
            ):
                descriptor = candidate
                break
        out.append({
            "schema": "onnx-splitpoint/required-profile-measurement",
            "schema_version": 3 if descriptor else 1,
            "model_id": str(model_id), "case_id": str(case_id),
            "backend": backend_n, "variant": variant_n,
            "run_id": str(run_id),
            "expected_setup_id": str(
                descriptor.get("expected_setup_id")
                or run.get("expected_setup_id") or run.get("setup_id") or ""
            ),
            "setup_id": str(
                descriptor.get("expected_setup_id")
                or run.get("expected_setup_id") or run.get("setup_id") or ""
            ),
            "measurement_endpoint": str(
                descriptor.get("measurement_endpoint")
                or run.get("measurement_endpoint") or ""
            ),
            "quality_endpoint": str(
                descriptor.get("quality_endpoint")
                or run.get("quality_endpoint") or ""
            ),
            "global_run_descriptor_sha256": str(
                descriptor.get("global_run_descriptor_sha256") or ""
            ),
            "endpoint_contract_id": str(
                descriptor.get("endpoint_contract_id") or ""
            ),
            "endpoint_contract_source": str(
                descriptor.get("endpoint_contract_source") or ""
            ),
        })

    for run in runs:
        if bool(run.get("deferred")) or run.get("required") is False:
            continue
        if _sealed_quality_only_identity_v27538(run, benchmark_plan):
            # Central Quality consumes the exact request identities.  No
            # Generic/performance row exists or is required for this recipe.
            continue
        if bool(
            run.get("semantic_reference_only")
            or run.get("canonical_cpu_reference")
        ):
            # The management ORT row produces semantic inputs for the quality
            # service.  It is intentionally absent from the performance/result
            # matrix and must not add full/split result expectations.
            continue
        rid = str(run.get("id") or run.get("run_id") or "").strip().lower().replace("-", "_")
        if rid == "ort_cpu":
            add("cpu_ort", "full", run_id=rid, run=run)
            for case_id in case_ids: add("cpu_ort", "split", case_id, rid, run)
        elif rid in {"ort_tensorrt", "tensorrt"}:
            reference_variants = reference_measurement_variants(run)
            if "full" in reference_variants:
                add("tensorrt", "full", run_id=rid, run=run)
            if "split" in reference_variants:
                for case_id in case_ids: add("tensorrt", "split", case_id, rid, run)
        elif rid in {"hailo8", "hailo8_full"}: add("hailo8", "full", run_id=rid, run=run)
        elif rid in {"hailo10", "hailo10h", "hailo10_full"}: add("hailo10", "full", run_id=rid, run=run)
        elif rid in {"deepx_m1_full", "deepx_full"}: add("deepx_m1", "full", run_id=rid, run=run)
        elif rid in {"deepx_m1_to_tensorrt", "deepx_m1_to_trt", "deepx_to_tensorrt"}:
            for case_id in case_ids: add("deepx_m1_to_tensorrt", "split", case_id, rid, run)
        elif rid in {"hailo8_to_trt", "hailo8_to_tensorrt"}:
            for case_id in case_ids: add("hailo8_to_tensorrt", "split", case_id, rid, run)
        elif rid in {"hailo10_to_trt", "hailo10_to_tensorrt"}:
            for case_id in case_ids: add("hailo10_to_tensorrt", "split", case_id, rid, run)
        elif rid in {"tensorrt_to_hailo8", "trt_to_hailo8"}:
            for case_id in case_ids: add("tensorrt_to_hailo8", "split", case_id, rid, run)
        elif rid in {"tensorrt_to_hailo10", "trt_to_hailo10"}:
            for case_id in case_ids: add("tensorrt_to_hailo10", "split", case_id, rid, run)
        elif rid in {"tensorrt_to_deepx", "tensorrt_to_deepx_m1", "trt_to_deepx"}:
            for case_id in case_ids: add("tensorrt_to_deepx_m1", "split", case_id, rid, run)
    return out


def _scope_base_key_v2796(row: Mapping[str, Any]) -> tuple[str, ...]:
    variant = str(
        row.get("quality_source_variant") or row.get("primary_variant")
        or row.get("variant") or ""
    ).strip().lower()
    if variant in {"composed", "complete"}:
        variant = "split"
    case_id = str(row.get("case_id") or "full").strip()
    if variant == "full":
        case_id = "full"
    return (
        str(row.get("model_id") or row.get("model") or "").strip().lower(),
        case_id.lower(),
        _logical_canonical_run_id(
            row.get("quality_source_run_id") or row.get("source_run_id")
            or row.get("run_id") or row.get("source_tag")
        ),
        _logical_canonical_backend(row.get("backend")),
        variant,
    )


def _canonical_endpoint_v2796(value: Any, task: Any = "") -> str:
    endpoint = str(value or "").strip().lower().replace(
        "-", "_"
    ).replace(" ", "_")
    task = str(task or "").strip().lower()
    if endpoint in {"p2", "part2", "raw_model_outputs"}:
        return "p2_output"
    if endpoint in {"completed_task", "task_complete"}:
        if task == "detection":
            return "completed_detection"
        if task == "classification":
            return "classification_logits"
    return endpoint


def _measurement_endpoint_v2796(row: Mapping[str, Any]) -> str:
    if row.get("runtime_ok") is False and not any(row.get(key) for key in (
        "measurement_endpoint", "performance_endpoint", "measured_endpoint",
    )):
        # ``endpoint_mode`` may be a normalizer compatibility default.  A
        # pre-runtime failure has no measured endpoint to infer from it.
        return ""
    return _canonical_endpoint_v2796(str(
        row.get("measurement_endpoint")
        or row.get("performance_endpoint")
        or row.get("measured_endpoint")
        or row.get("endpoint_mode")
        or ""
    ), row.get("task"))


def _bind_results_to_required_scope_v2796(
    expected: Sequence[Mapping[str, Any]],
    measured: Sequence[Mapping[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Bind direct result rows to immutable physical scope identities."""

    by_base: Dict[Tuple[str, ...], List[Mapping[str, Any]]] = {}
    for row in expected:
        by_base.setdefault(_scope_base_key_v2796(row), []).append(row)
    out: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    for ordinal, raw in enumerate(measured):
        row = dict(raw)
        candidates = by_base.get(_scope_base_key_v2796(row), [])
        setups = _logical_direct_setup_ids(row)
        measured_setup = setups[0] if len(setups) == 1 else ""
        measured_endpoint = _measurement_endpoint_v2796(row)
        dispatch_terminal_failure = bool(
            row.get("source_context_binding_status") == "exact_dispatch_copy_match"
            and row.get("runtime_ok") is False
            and str(row.get("error_class") or row.get("error_detail") or "").strip()
            and not measured_endpoint
            and all(row.get(key) in (None, "") for key in (
                "total_latency_ms", "full_latency_ms", "throughput_primary_fps",
            ))
        )
        exact: list[Mapping[str, Any]] = []
        for candidate in candidates:
            if row.get("source_context_binding_status") in {"ambiguous", "conflict"}:
                continue
            if dispatch_terminal_failure and not (
                candidate.get("terminal_outcome_required") is True
                and candidate.get("success_required") is False
            ):
                continue
            expected_setup = str(
                candidate.get("expected_setup_id")
                or candidate.get("setup_id") or ""
            ).strip().lower().replace("-", "_").replace(" ", "_")
            expected_endpoint = _canonical_endpoint_v2796(
                candidate.get("measurement_endpoint"),
                candidate.get("task") or row.get("task"),
            )
            if expected_setup and expected_setup != measured_setup:
                continue
            if expected_endpoint and expected_endpoint != measured_endpoint and not (
                dispatch_terminal_failure
                and candidate.get("terminal_outcome_required") is True
                and candidate.get("success_required") is False
            ):
                continue
            measured_quality = _canonical_endpoint_v2796(
                row.get("quality_endpoint"), row.get("task"),
            )
            expected_quality = _canonical_endpoint_v2796(
                candidate.get("quality_endpoint"),
                candidate.get("task") or row.get("task"),
            )
            if measured_quality and expected_quality and (
                measured_quality != expected_quality
            ):
                continue
            exact.append(candidate)
        if len(exact) == 1:
            candidate = exact[0]
            logical_sha = str(
                candidate.get("logical_identity_sha256") or ""
            ).strip()
            if logical_sha:
                row["logical_identity_sha256"] = logical_sha
            row["required_scope_binding_status"] = (
                "exact_terminal_failure" if dispatch_terminal_failure
                else "exact_physical_match"
            )
            row["required_scope_expected_setup_id"] = str(
                candidate.get("expected_setup_id")
                or candidate.get("setup_id") or ""
            )
            row["required_scope_measurement_endpoint"] = str(
                candidate.get("measurement_endpoint") or ""
            )
            row["required_scope_quality_endpoint"] = str(
                candidate.get("quality_endpoint") or ""
            )
        else:
            reason = (
                "scope_identity_ambiguous" if len(exact) > 1
                else "scope_identity_physical_mismatch"
            )
            row["required_scope_binding_status"] = reason
            errors.append({
                "error_class": reason,
                "row_ordinal": ordinal,
                "base_identity": list(_scope_base_key_v2796(row)),
                "direct_setup_ids": setups,
                "measurement_endpoint": measured_endpoint,
                "candidate_count": len(candidates),
                "exact_candidate_count": len(exact),
                "source_path": str(row.get("source_path") or ""),
                "source_context_binding_error": str(row.get("source_context_binding_error") or ""),
            })
        out.append(row)
    return out, errors


def _required_scope_key_v2796(row: Mapping[str, Any]) -> tuple[str, ...]:
    logical_sha = str(row.get("logical_identity_sha256") or "").strip().lower()
    if logical_sha:
        return ("sha256", logical_sha)
    base = _scope_base_key_v2796(row)
    strict_physical = bool(
        str(row.get("expected_setup_id") or "").strip()
        or str(row.get("measurement_endpoint") or "").strip()
        or str(row.get("required_scope_binding_status") or "").strip()
    )
    if not strict_physical:
        # Historical post-generation plans did not seal model/run/setup/
        # endpoint identity.  Keep their old backend/variant/case projection
        # only behind the explicit legacy path; strict v3 rows always carry a
        # receipt SHA and never reach this branch.
        return ("legacy", base[3], base[4], base[1])
    setup = str(
        row.get("expected_setup_id") or row.get("setup_id") or ""
    ).strip().lower().replace("-", "_").replace(" ", "_")
    endpoint = _measurement_endpoint_v2796(row)
    return ("physical", *base, setup, endpoint)


def missing_profile_measurements_v60r(expected: Sequence[Mapping[str, Any]], measured: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
    measured_keys = {
        _required_scope_key_v2796(row) for row in measured
        if str(row.get("required_scope_binding_status") or "")
        in {"", "exact_physical_match", "exact_terminal_failure"}
    }
    missing: list[dict[str, Any]] = []
    for row in expected:
        if _required_scope_key_v2796(row) not in measured_keys:
            item = dict(row); item.update({"error_class": "selected_profile_measurement_missing", "status": "missing"}); missing.append(item)
    return missing


def required_profile_outcomes_v282(
    required: Sequence[Mapping[str, Any]], logical_rows: Sequence[Mapping[str, Any]],
    observations: Sequence[Mapping[str, Any]], readiness: Mapping[str, Any],
) -> dict[str, Any]:
    """Shared production/replay projection; leaves all measurements intact."""
    from ..native_job_identity import required_profile_build_exclusions
    missing = missing_profile_measurements_v60r(required, logical_rows)
    conflicts: list[dict[str, Any]] = []
    excluded = required_profile_build_exclusions(
        missing, readiness, observations, diagnostics=conflicts,
    )
    excluded_keys = {row.get('logical_identity_sha256') for row in excluded}
    missing = [row for row in missing if row.get('logical_identity_sha256') not in excluded_keys]
    duplicates = duplicate_profile_measurements_v269d(required, logical_rows)
    return {
        'required_results': [dict(row) for row in required],
        'required_result_count': len(required),
        'missing_results': missing, 'missing_result_count': len(missing),
        'excluded_results': excluded, 'excluded_result_count': len(excluded),
        'duplicate_results': duplicates, 'duplicate_result_count': len(duplicates),
        'build_exclusion_conflicts': conflicts,
        'build_exclusion_conflict_count': len(conflicts),
        'measurement_values_synthesized': False,
    }


def duplicate_profile_measurements_v269d(
    expected: Sequence[Mapping[str, Any]],
    measured: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Reject duplicate rows for one logical profile measurement.

    Full baselines are model-level facts, so their logical case is always
    ``full``.  This postcondition would have caught the 2.69e 63-vs-48 matrix
    even though every required key was technically present.
    """
    expected_by_key = {
        _required_scope_key_v2796(row): dict(row) for row in expected
    }
    counts: Dict[Tuple[str, ...], int] = {}
    sources: Dict[Tuple[str, ...], List[str]] = {}
    for row in measured:
        if str(row.get("required_scope_binding_status") or "") not in {
            "", "exact_physical_match", "exact_terminal_failure",
        }:
            continue
        key = _required_scope_key_v2796(row)
        if key not in expected_by_key:
            continue
        counts[key] = counts.get(key, 0) + 1
        path = str(row.get("source_path") or "").strip()
        if path:
            sources.setdefault(key, []).append(path)
    duplicates: list[dict[str, Any]] = []
    for key, count in sorted(counts.items()):
        if count <= 1:
            continue
        expected_row = expected_by_key[key]
        item: dict[str, Any] = {
            "status": "duplicate",
            "error_class": "duplicate_selected_profile_measurement",
            "backend": str(expected_row.get("backend") or ""),
            "variant": str(expected_row.get("variant") or ""),
            "case_id": str(expected_row.get("case_id") or ""),
            "row_count": count,
            "source_paths": sorted(set(sources.get(key) or [])),
        }
        if str(expected_row.get("logical_identity_sha256") or "").strip():
            item.update({
                "logical_identity_sha256": str(
                    expected_row.get("logical_identity_sha256") or ""
                ),
                "run_id": str(expected_row.get("run_id") or ""),
                "setup_id": str(
                    expected_row.get("expected_setup_id")
                    or expected_row.get("setup_id") or ""
                ),
                "measurement_endpoint": str(
                    expected_row.get("measurement_endpoint") or ""
                ),
            })
        duplicates.append(item)
    return duplicates


def validation_cardinality_mismatches_v60r(*, benchmark_plan: Mapping[str, Any] | None, normalized_rows: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
    requested_values: set[int] = set()
    for r in list((benchmark_plan or {}).get("runs") or []):
        if not isinstance(r, Mapping) or _sealed_quality_only_identity_v27538(r, benchmark_plan) or bool(r.get("deferred")) or r.get("required") is False or not (bool(r.get("validation_budget_authoritative")) or "validation_items_requested" in r):
            continue
        try:
            v = int(r.get("validation_items_requested") or 0)
        except Exception:
            v = 0
        if v > 0: requested_values.add(v)
    if not requested_values: return []
    if len(requested_values) != 1:
        return [{"status": "mismatch", "reason": "inconsistent_requested_counts", "requested_counts": sorted(requested_values)}]
    expected = next(iter(requested_values)); mismatches: list[dict[str, Any]] = []; observed_any = False
    for plan_row in list((benchmark_plan or {}).get("runs") or []):
        if not isinstance(plan_row, Mapping) or _sealed_quality_only_identity_v27538(plan_row, benchmark_plan) or bool(plan_row.get("deferred")) or plan_row.get("required") is False or not (bool(plan_row.get("validation_budget_authoritative")) or "validation_items_requested" in plan_row):
            continue
        try:
            configured = int(plan_row.get("validation_max_images") or 0)
        except Exception:
            configured = -1
        if configured != expected:
            mismatches.append({
                "status": "mismatch", "phase": "benchmark_plan",
                "run_id": plan_row.get("id") or plan_row.get("run_id"),
                "requested_count": expected, "configured_max_images": configured,
                "reason": "run_mode_budget_not_applied_to_plan",
            })
    for row in normalized_rows:
        contract = row.get("validation_cardinality_contract") if isinstance(row.get("validation_cardinality_contract"), Mapping) else {}
        actual = contract.get("evaluated_count") if contract else None
        if actual in (None, ""):
            gate = row.get("task_quality_gate") if isinstance(row.get("task_quality_gate"), Mapping) else {}
            actual = gate.get("n")
        try: actual_i = int(actual)
        except Exception: continue
        if actual_i <= 0: continue
        observed_any = True
        if actual_i != expected or (contract and contract.get("pass") is False):
            mismatches.append({"status": "mismatch", "model_id": row.get("model_id"), "case_id": row.get("case_id"),
                               "backend": row.get("backend"), "variant": row.get("variant"), "requested_count": expected,
                               "evaluated_count": actual_i, "contract": dict(contract)})
    if not observed_any:
        mismatches.append({"status": "unavailable", "reason": "no_runtime_cardinality_evidence", "requested_count": expected})
    return mismatches


def _benchmark_stage_status_v60r(*, normalized_row_count: int, executor_status: Any, executor_metrics: Optional[Mapping[str, Any]] = None, required_missing_count: int = 0, cardinality_mismatch_count: int = 0) -> str:
    metrics = dict(executor_metrics or {})
    executor_state = str(executor_status or "").strip().lower()
    if metrics.get("remote_dispatched") is False:
        if executor_state == "failed_to_dispatch" and bool(
            metrics.get("remote_dispatch_failed")
        ):
            return "failed"
        if executor_state == "cancelled" and bool(
            metrics.get("cancelled_before_dispatch")
        ):
            return "cancelled"
    if (
        metrics.get("performance_matrix_applicable") is False
        and metrics.get("quality_evidence_only_complete") is not True
    ):
        return "partial"
    if (
        metrics.get("performance_matrix_applicable") is False
        and metrics.get("quality_evidence_only_complete") is True
        and executor_state in {"ok", "success", "completed"}
        and int(required_missing_count or 0) == 0
        and int(cardinality_mismatch_count or 0) == 0
    ):
        return "ok"
    base = _benchmark_stage_status_v60p(normalized_row_count=normalized_row_count, executor_status=executor_status, executor_metrics=executor_metrics)
    return "partial" if int(required_missing_count or 0) > 0 or int(cardinality_mismatch_count or 0) > 0 else base


def benchmark_set_postcondition_v60v(base_dir: Path) -> dict[str, Any]:
    """Validate that a generated BenchmarkSet is safe to dispatch.

    A partially written suite may still contain ONNX/HEF/DXNN artifacts while
    lacking the final case contract.  Remote-dispatching such a directory only
    produces cascading ``benchmark_set.json has no cases`` errors.  This
    postcondition therefore treats the suite contract, case directories, run
    plan and executable harness as one atomic generation result.
    """
    base = Path(base_dir)
    candidates = [
        base / "legacy_suite",
        base / "generated_suite",
        base / "suite",
        base,
    ]
    candidates = list(dict.fromkeys(candidates))
    reports: list[dict[str, Any]] = []
    for suite in candidates:
        contract_path = suite / "benchmark_set.json"
        plan_path = suite / "benchmark_plan.json"
        harness_path = suite / "benchmark_suite.py"
        contract = read_json(contract_path, default={}) or {}
        plan = read_json(plan_path, default={}) or {}
        cases_raw = list(contract.get("cases") or []) if isinstance(contract, Mapping) else []
        case_ids: list[str] = []
        for row in cases_raw:
            cid = _canonical_benchmark_case_id_v27919(row)
            if cid:
                case_ids.append(cid)
        existing_case_ids = sorted({d.name for d in suite.glob("b*") if d.is_dir()}) if suite.exists() else []
        missing_case_dirs = [cid for cid in case_ids if cid not in existing_case_ids]
        runs = [r for r in list(plan.get("runs") or []) if isinstance(r, Mapping)] if isinstance(plan, Mapping) else []
        valid = bool(
            contract_path.is_file()
            and harness_path.is_file()
            and case_ids
            and not missing_case_dirs
            and runs
        )
        reasons: list[str] = []
        if not contract_path.is_file(): reasons.append("benchmark_set_json_missing")
        if contract_path.is_file() and not case_ids: reasons.append("benchmark_set_has_no_cases")
        if missing_case_dirs: reasons.append("benchmark_case_directories_missing")
        if not plan_path.is_file(): reasons.append("benchmark_plan_json_missing")
        elif not runs: reasons.append("benchmark_plan_has_no_runs")
        if not harness_path.is_file(): reasons.append("benchmark_suite_script_missing")
        reports.append({
            "suite_dir": str(suite),
            "contract_path": str(contract_path),
            "plan_path": str(plan_path),
            "harness_path": str(harness_path),
            "case_ids": case_ids,
            "case_count": len(case_ids),
            "existing_case_ids": existing_case_ids,
            "missing_case_dirs": missing_case_dirs,
            "run_count": len(runs),
            "valid": valid,
            "reasons": reasons,
        })
    selected = next((r for r in reports if r.get("valid")), None)
    if selected is None:
        selected = max(reports, key=lambda r: (int(r.get("case_count") or 0), int(r.get("run_count") or 0)), default={})
    return {
        "schema": "onnx-splitpoint/benchmark-set-postcondition",
        "schema_version": 1,
        "created_at": now_iso(),
        "valid": bool(selected.get("valid")) if isinstance(selected, Mapping) else False,
        "selected_suite_dir": str(selected.get("suite_dir") or "") if isinstance(selected, Mapping) else "",
        "case_count": int(selected.get("case_count") or 0) if isinstance(selected, Mapping) else 0,
        "run_count": int(selected.get("run_count") or 0) if isinstance(selected, Mapping) else 0,
        "reasons": list(selected.get("reasons") or []) if isinstance(selected, Mapping) else ["no_suite_candidates"],
        "candidates": reports,
    }


def _model_row_suite_import_allowed_v27519(options: Any) -> bool:
    """A fresh field run must generate from its current logical profile."""

    return not bool(getattr(options, "require_fresh_run", False))

