def _vendor_full_completed_quality_fields_v282(result: Mapping[str, Any], identity: Mapping[str, Any]) -> dict[str, Any]:
    """Transport the existing exact central completed endpoint, without relabeling raw outputs."""
    if result.get("quality_join_endpoint") != "completed_task_decoded_nms":
        return {}
    from ..native_detection_postprocess import verify_completed_detection_comparison_endpoint_contract
    fields = ("quality_join_endpoint", "completed_task_endpoint_contract",
              "completed_task_endpoint_contract_hash", "completed_task_output_endpoint_id")
    for field in fields:
        if result.get(field) != identity.get(field) or result.get(field) in (None, "", {}):
            raise ValueError("central_vendor_full_completed_endpoint_alias_mismatch:" + field)
    contract = verify_completed_detection_comparison_endpoint_contract(result["completed_task_endpoint_contract"])
    if (contract["endpoint_contract_hash"] != result["completed_task_endpoint_contract_hash"]
            or contract["output_endpoint_id"] != result["completed_task_output_endpoint_id"]):
        raise ValueError("central_vendor_full_completed_endpoint_identity_mismatch")
    return {field: result[field] for field in fields}
